export type SettledArmRoot = {
	readonly __marklessSettledArms?: ReadonlyArray<MarklessSettledArmHandoff>;
};

type RenderedArm = {
	readonly armRecords?: unknown;
	readonly computed?: ReadonlyArray<Record<string, unknown>>;
