		readonly behaviors?: ReadonlyArray<{
			readonly symbolId?: unknown;
			readonly inputGraphReads?: ReadonlyArray<{ readonly graphNodeId?: unknown }>;
		}>;
		readonly keyedRepeats?: ProtocolViewPayload['keyedRepeats'];
